rained\"}} -->\n<div class=\"wp-block-group alignfull\" id=\"services\" style=\"padding-top:33px;padding-bottom:0px\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Books:</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"margin\":{\"top\":\"50px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:50px\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-cover\"} -->\n<figure class=\"wp-block-image size-full book-cover\"><img src=\"http://localhost/wp-content/uploads/2025/10/01_calvin_hobbes.jpg\" alt=\"\" class=\"wp-image-84\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading\" style=\"margin-top:16px\"><a href=\"http://localhost/books/calvin-and-hobbes/\">Calvin and Hobbes</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This is only the beginning! The very first volume of Calvin and Hobbes introduces the world to the most unforgettable duo in comics.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":43,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-cover\"} -->\n<figure class=\"wp-block-image size-full book-cover\"><img src=\"http://localhost/wp-content/uploads/2025/10/ch-book-02.jpg\" alt=\"\" class=\"wp-image-43\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"16px\"}}}} -->\n<h3 class=\"wp-block-heading\" style=\"margin-top:16px\"><a href=\"http://localhost/books/the-authoritative-calvin-and-hobbes/\" data-type=\"link\" data-id=\"http://localhost/books/the-authoritative-calvin-and-hobbes/\">The Authoritative Calvin and Hobbes</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>What happens when bath time becomes a Yukon expedition—or school avoidance turns into interplanetary travel?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"8px\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":97,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"book-cover\"} -->\n<figure class=\"wp-block-image size-full book-cover\"><img src=\"http://localhost/wp-content/uploads/2025/10/06_weirdos_from_another_planet.jpg\" alt=\"\" class=\"wp-image-97\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}}}} -->\n<h3 class=\"wp-block-heading\" style=\"margin-top:20px\"><a href=\"http://localhost/books/weirdos-from-another-planet/\" data-type=\"link\" data-id=\"http://localhost/books/weirdos-from-another-planet/\">Weirdos from Another Planet</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>From interplanetary escapes to snowman invasions, Weirdos from Another Planet! is packed with laugh-out-loud comics and signature Calvin and Hobbes chaos.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"21px\"} -->\n<div style=\"height:21px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Reviews of Calvin and Hobbes</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[hh_random_review]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"ast-global-color-4\",\"layout\":{\"inherit\":false,\"contentSize\":\"800px\",\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-ast-global-color-4-background-color has-background\" id=\"reviews\"><!-- wp:para